    var mark = !has && MARK[pose] ? h('text', { x: 50, y: 7, fontSize: 7, fontFamily: 'var(--font-stroke)', fill: pose === 'done' ? COLORS.green : pose === 'fail' ? COLORS.red : COLORS.orange }, MARK[pose]) : null;
